arguments.command:
python3 << 'EOF'
import json
d=json.load(open('bench/results/2026-10-12/m1-ngram/recon/inventory.json'))
for r in d.get('runs',[]):
    if 'mem0-r0' in str(r):
        print('run:', r.get('run_id') if 'run_id' in r else r.get('id'))
        for st in r.get('steps',[]):
            for rec in st.get('records', st.get('tap_records', [])):
                if rec.get('role')=='agent' and st.get('step')==0:
                    print('  agent step0:', rec.get('n'), 'reqs', rec.get('prompt_n'), rec.get('predicted_n'))
EOF
grep -n "10\|11" bench/results/2026-10-12/m1-ngram/recon/inventory.json | head

